package oidc

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"time"

	gooidc "github.com/coreos/go-oidc/v3/oidc"
	"golang.org/x/oauth2"
	"golang.org/x/oauth2/github"
)

// AuthRequest is what a provider builds its authorization URL from. Every
// value is generated by this flow or built from configuration; none comes
// from the request that started the sign-in.
type AuthRequest struct {
	State       string
	Nonce       string
	Challenge   string // PKCE S256 challenge of Verifier
	RedirectURI string
}

// ExchangeRequest is what a provider redeems an authorization code with.
type ExchangeRequest struct {
	Code        string
	Verifier    string // the PKCE verifier whose challenge went out
	Nonce       string // the nonce that went out; an OIDC provider requires the id_token to echo it
	RedirectURI string
}

// Provider is one identity provider's authorize-URL and code-exchange flow.
// Exchange returns claims it has verified, or an error whose text carries no
// token, code or secret. An implementation reports EmailVerified only when the
// provider vouched for the address.
type Provider interface {
	ID() string
	AuthURL(a AuthRequest) string
	Exchange(ctx context.Context, x ExchangeRequest) (*Claims, error)
}

// httpTimeout bounds every call to a provider.
const httpTimeout = 15 * time.Second

// maxBody bounds any provider response body this package reads.
const maxBody = 1 << 20

// withClient puts hc where oauth2 and go-oidc look for the HTTP client.
func withClient(ctx context.Context, hc *http.Client) context.Context {
	ctx = context.WithValue(ctx, oauth2.HTTPClient, hc)
	return gooidc.ClientContext(ctx, hc)
}

// pkceOptions are the authorization-URL parameters of a PKCE S256 request.
func pkceOptions(challenge string) []oauth2.AuthCodeOption {
	return []oauth2.AuthCodeOption{
		oauth2.SetAuthURLParam("code_challenge", challenge),
		oauth2.SetAuthURLParam("code_challenge_method", "S256"),
	}
}

// ---- GitHub (plain OAuth2, PKCE S256) ----

// githubURLs are GitHub's endpoints; a test points them at a fake.
type githubURLs struct {
	endpoint oauth2.Endpoint
	api      string
}

// defaultGitHub is GitHub's endpoints (a function: a package-level value would
// be shared mutable state).
func defaultGitHub() githubURLs {
	return githubURLs{endpoint: github.Endpoint, api: "https://api.github.com"}
}

type githubProvider struct {
	cfg  ProviderConfig
	urls githubURLs
	hc   *http.Client
}

func newGitHub(cfg ProviderConfig, hc *http.Client, urls githubURLs) Provider {
	return &githubProvider{cfg: cfg, urls: urls, hc: hc}
}

func (p *githubProvider) ID() string { return p.cfg.ID }

func (p *githubProvider) oauthConfig(redirectURI string) *oauth2.Config {
	scopes := p.cfg.Scopes
	if len(scopes) == 0 {
		scopes = []string{"read:user", "user:email"}
	}
	return &oauth2.Config{
		ClientID: p.cfg.ClientID, ClientSecret: p.cfg.ClientSecret,
		Endpoint: p.urls.endpoint, RedirectURL: redirectURI, Scopes: scopes,
	}
}

// AuthURL sends PKCE S256 too: GitHub supports it, and a code intercepted
// without the verifier is worthless (HEAD omitted it).
func (p *githubProvider) AuthURL(a AuthRequest) string {
	return p.oauthConfig(a.RedirectURI).AuthCodeURL(a.State, pkceOptions(a.Challenge)...)
}

func (p *githubProvider) Exchange(ctx context.Context, x ExchangeRequest) (*Claims, error) {
	ctx = withClient(ctx, p.hc)
	cfg := p.oauthConfig(x.RedirectURI)
	tok, err := cfg.Exchange(ctx, x.Code, oauth2.SetAuthURLParam("code_verifier", x.Verifier))
	if err != nil {
		return nil, fmt.Errorf("github: code exchange: %w", errClass(err))
	}
	client := cfg.Client(ctx, tok)
	var profile struct {
		ID   int64  `json:"id"`
		Name string `json:"name"`
	}
	if err := p.getJSON(ctx, client, "/user", &profile); err != nil {
		return nil, fmt.Errorf("github: fetch user: %w", err)
	}
	if profile.ID == 0 {
		return nil, errors.New("github: the profile has no id")
	}
	var emails []struct {
		Email    string `json:"email"`
		Primary  bool   `json:"primary"`
		Verified bool   `json:"verified"`
	}
	if err := p.getJSON(ctx, client, "/user/emails", &emails); err != nil {
		return nil, fmt.Errorf("github: fetch emails: %w", err)
	}
	email, verified := "", false
	for _, e := range emails { // the primary verified address, never an unverified one
		if e.Primary && e.Verified {
			email, verified = e.Email, true
			break
		}
	}
	if !verified {
		for _, e := range emails { // else any verified address
			if e.Verified {
				email, verified = e.Email, true
				break
			}
		}
	}
	return &Claims{
		Provider: p.cfg.ID, Subject: fmt.Sprintf("%d", profile.ID),
		Email: email, EmailVerified: verified, Name: profile.Name,
	}, nil
}

func (p *githubProvider) getJSON(ctx context.Context, client *http.Client, path string, out any) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.urls.api+path, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := client.Do(req)
	if err != nil {
		return errClass(err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("GET %s: status %d", path, resp.StatusCode)
	}
	return json.NewDecoder(io.LimitReader(resp.Body, maxBody)).Decode(out)
}

// ---- generic OIDC (discovery, PKCE S256, nonce) ----

type oidcProvider struct {
	cfg      ProviderConfig
	hc       *http.Client
	provider *gooidc.Provider
	verifier *gooidc.IDTokenVerifier
}

// newOIDC discovers the provider's endpoints from its issuer (a network call)
// and builds the id_token verifier: signature against the issuer's keys,
// issuer, audience (this client) and expiry, all checked by go-oidc.
func newOIDC(ctx context.Context, cfg ProviderConfig, hc *http.Client) (Provider, error) {
	dctx, cancel := context.WithTimeout(withClient(ctx, hc), httpTimeout)
	defer cancel()
	prov, err := gooidc.NewProvider(dctx, cfg.Issuer)
	if err != nil {
		return nil, fmt.Errorf("oidc: provider %s: discovery: %w", cfg.ID, errClass(err))
	}
	// Discovery is the issuer's own document, but a plain-http endpoint in it
	// would send the code, the verifier and the client secret in the clear.
	var meta struct {
		JWKSURI string `json:"jwks_uri"`
	}
	if err := prov.Claims(&meta); err != nil {
		return nil, fmt.Errorf("oidc: provider %s: discovery document cannot be read", cfg.ID)
	}
	ep := prov.Endpoint()
	for _, u := range []string{ep.AuthURL, ep.TokenURL, meta.JWKSURI} {
		if !httpsURL(u) {
			return nil, fmt.Errorf("oidc: provider %s: discovery names an endpoint that is not https", cfg.ID)
		}
	}
	return &oidcProvider{
		cfg: cfg, hc: hc, provider: prov,
		verifier: prov.Verifier(&gooidc.Config{ClientID: cfg.ClientID}),
	}, nil
}

// httpsURL reports whether raw is an absolute https URL without userinfo.
func httpsURL(raw string) bool {
	u, err := url.Parse(raw)
	return err == nil && u.Scheme == "https" && u.Host != "" && u.User == nil
}

func (p *oidcProvider) ID() string { return p.cfg.ID }

func (p *oidcProvider) oauthConfig(redirectURI string) *oauth2.Config {
	scopes := p.cfg.Scopes
	if len(scopes) == 0 {
		scopes = []string{gooidc.ScopeOpenID, "email", "profile"}
	} else if !slices.Contains(scopes, gooidc.ScopeOpenID) {
		scopes = append([]string{gooidc.ScopeOpenID}, scopes...)
	}
	return &oauth2.Config{
		ClientID: p.cfg.ClientID, ClientSecret: p.cfg.ClientSecret,
		Endpoint: p.provider.Endpoint(), RedirectURL: redirectURI, Scopes: scopes,
	}
}

func (p *oidcProvider) AuthURL(a AuthRequest) string {
	opts := append(pkceOptions(a.Challenge), oauth2.SetAuthURLParam("nonce", a.Nonce))
	return p.oauthConfig(a.RedirectURI).AuthCodeURL(a.State, opts...)
}

func (p *oidcProvider) Exchange(ctx context.Context, x ExchangeRequest) (*Claims, error) {
	ctx = withClient(ctx, p.hc)
	if x.Nonce == "" {
		return nil, errors.New("oidc: no nonce to check the id_token against")
	}
	tok, err := p.oauthConfig(x.RedirectURI).Exchange(ctx, x.Code, oauth2.SetAuthURLParam("code_verifier", x.Verifier))
	if err != nil {
		return nil, fmt.Errorf("oidc: code exchange: %w", errClass(err))
	}
	raw, _ := tok.Extra("id_token").(string)
	if raw == "" {
		return nil, errors.New("oidc: no id_token in the token response")
	}
	idTok, err := p.verifier.Verify(ctx, raw)
	if err != nil {
		return nil, fmt.Errorf("oidc: verify id_token: %w", errClass(err))
	}
	// The nonce binds this id_token to the sign-in that asked for it: a token
	// minted for another request (a replay, an injected one) does not echo it.
	if !sameSecret(idTok.Nonce, x.Nonce) {
		return nil, errors.New("oidc: id_token nonce does not match the sign-in")
	}
	var c struct {
		Sub   string `json:"sub"`
		Email string `json:"email"`
		// EmailVerified is a bool at most providers and the string "true" at a
		// few; only those two values vouch for the address.
		EmailVerified any    `json:"email_verified"`
		Name          string `json:"name"`
		Azp           string `json:"azp"`
	}
	if err := idTok.Claims(&c); err != nil {
		return nil, errors.New("oidc: id_token claims cannot be read")
	}
	// OIDC Core 3.1.3.7: with several audiences azp must be present, and a
	// present azp must be this client: a token minted for another client of the
	// same issuer that merely lists ours is not a sign-in to ours.
	if (len(idTok.Audience) > 1 || c.Azp != "") && !sameSecret(c.Azp, p.cfg.ClientID) {
		return nil, errors.New("oidc: id_token was issued to another client (azp)")
	}
	if c.Sub == "" {
		return nil, errors.New("oidc: id_token has no subject")
	}
	return &Claims{Provider: p.cfg.ID, Subject: c.Sub, Email: c.Email, EmailVerified: emailVerified(c.EmailVerified), Name: c.Name}, nil
}

// emailVerified reads an email_verified claim: the JSON boolean true or the
// string "true", nothing else (not "True", not 1, not a missing claim).
func emailVerified(v any) bool {
	switch x := v.(type) {
	case bool:
		return x
	case string:
		return x == "true"
	}
	return false
}

// errClass reduces a provider-library error to a text that cannot quote a
// response body, a token or a client secret: the library's OAuth2 errors embed
// the provider's body, and transport errors embed a URL. Only the class and,
// for an OAuth2 error response, the standard error code survive.
func errClass(err error) error {
	if err == nil {
		return nil
	}
	if re, ok := errors.AsType[*oauth2.RetrieveError](err); ok {
		code := re.ErrorCode
		if code == "" || len(code) > 64 || strings.ContainsAny(code, " \t\r\n\"") {
			code = "unspecified"
		}
		return fmt.Errorf("the token endpoint refused the request (status %d, error %s)", re.Response.StatusCode, code)
	}
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return errors.New("timed out")
	case errors.Is(err, context.Canceled):
		return errors.New("canceled")
	}
	return errors.New("the provider could not be reached or answered unexpectedly")
}
